INSERT INTO assessment_questions (domain_id, question_text, question_type, response_options, age_group, respondent_type, cultural_context, order_index, is_follow_up, baseline_question_id) VALUES
((SELECT id FROM assessment_domains WHERE code = 'autism_toddler'), 'Since our last assessment, has your child shown improvement in playing with other children?', 'scale', '{"options": [{"value": 0, "label": "Much Worse"}, {"value": 1, "label": "Worse"}, {"value": 2, "label": "No Change"}, {"value": 3, "label": "Better"}, {"value": 4, "label": "Much Better"}]}', 'toddler', 'parent', '{"follow_up_type": "progress_tracking"}', 1, true, (SELECT id FROM assessment_questions WHERE domain_id = (SELECT id FROM assessment_domains WHERE code = 'autism_toddler') AND order_index = 1)),
((SELECT id FROM assessment_domains WHERE code = 'autism_toddler'), 'How would you rate your child''s overall social interaction progress this month?', 'scale', '{"options": [{"value": 0, "label": "No Progress"}, {"value": 1, "label": "Minimal Progress"}, {"value": 2, "label": "Some Progress"}, {"value": 3, "label": "Good Progress"}, {"value": 4, "label": "Excellent Progress"}]}', 'toddler', 'parent', '{"follow_up_type": "overall_progress"}', 2, true, null),
((SELECT id FROM assessment_domains WHERE code = 'adhd_child'), 'Compared to last month, how is your child''s attention span during homework or chores?', 'scale', '{"options": [{"value": 0, "label": "Much Worse"}, {"value": 1, "label": "Worse"}, {"value": 2, "label": "No Change"}, {"value": 3, "label": "Better"}, {"value": 4, "label": "Much Better"}]}', 'child_adolescent', 'parent', '{"follow_up_type": "progress_tracking"}', 1, true, (SELECT id FROM assessment_questions WHERE domain_id = (SELECT id FROM assessment_domains WHERE code = 'adhd_child') AND order_index = 1));
